import os
import subprocess
from dataclasses import dataclass

import requests
from langchain_core.tools import tool


@dataclass
class RepoCheckResult:
    repo_url: str
    passed: bool
    notified: bool


@tool
def verify_backup_repo_and_notify(repo_url: str, read_data_subset: str = "") -> RepoCheckResult:
    cmd = ["restic", "-r", repo_url, "check"]
    if read_data_subset:
        cmd.append(f"--read-data-subset={read_data_subset}")
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
    passed = proc.returncode == 0
    text = f"Backup repo check {'PASSED' if passed else 'FAILED'} for {repo_url}\n```{(proc.stdout or proc.stderr)[-1500:]}```"
    resp = requests.post(os.environ["SLACK_STORAGE_WEBHOOK_URL"], json={"text": text}, timeout=10)
    return RepoCheckResult(repo_url=repo_url, passed=passed, notified=resp.ok)

import json
import subprocess
from pathlib import Path


def validate_restored_objects_against_manifest(manifest_path: str, restore_dir: str) -> dict:
    m = json.loads(Path(manifest_path).read_text())
    root = Path(restore_dir)
    ok, bad, miss = [], [], []
    paths = {}
    for k in m:
        p = root / k
        if p.is_file():
            paths[str(p)] = k
        else:
            miss.append(k)
    if paths:
        r = subprocess.run(
            ["sha256sum", "--", *paths.keys()],
            capture_output=True,
            text=True,
            check=True,
        )
        for ln in r.stdout.splitlines():
            h, _, f = ln.partition("  ")
            k = paths.get(f)
            if k is None:
                continue
            (ok if h.lower() == m[k].lower() else bad).append(k)
    return {
        "total": len(m),
        "matched": len(ok),
        "mismatched": bad,
        "missing": miss,
    }
